  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 The Sonnet: Shakespeare and Poetic Form$j$, $j${"readings": [{"title": "Psalm 8 (King James Version)", "url": "/portal/bible/Psalms/8"}], "body": "The Renaissance, meaning rebirth, was a period of new learning, art and exploration in Europe from about 1400 to 1600. In England it reached its height under Queen Elizabeth I, when William Shakespeare, born in 1564, wrote his plays and poems.\n\nA sonnet is a fourteen line poem with a fixed form. The English or Shakespearean sonnet has three quatrains of four lines each and a closing couplet of two lines, rhyming ABAB CDCD EFEF GG. Each line is usually written in iambic pentameter, five beats of an unstressed syllable followed by a stressed one. Say it aloud: Shall I compare thee to a summer's day? The ten syllables fall into a steady da DUM pattern.\n\nMost sonnets have a volta, a turn in thought. In Shakespeare's sonnets the volta often comes at the couplet, which gives a final twist or conclusion. Sonnet 18 begins by comparing a loved one to a summer day, finds summer too short and changeable, and ends by claiming that the poem itself will keep the beloved alive.\n\nTo read a sonnet, mark the rhyme scheme, find the turn, and state in one sentence the argument of the whole poem.\n\nYour task: (1) Describe the structure of a Shakespearean sonnet. (2) Explain iambic pentameter in your own words. (3) Write what you think a volta does in a poem, and give an example from any sonnet you read.\n\nFlorida standards: ELA.12.R.1.4, ELA.12.R.3.1, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.4, ELA.12.R.3.1, ELA.K12.EE.1.1", "script": "Welcome to the Renaissance. Listen, that word means rebirth, and it describes a time from about 1400 to 1600 when Europe was alive with new learning, new art and new exploration. In England it reached its height under Queen Elizabeth the First, and a man named William Shakespeare was born in 1564.\n\nWe begin with his poems. A sonnet is a fourteen line poem with a fixed form. The English or Shakespearean sonnet has three groups of four lines, called quatrains, and a final two line couplet. The rhyme scheme is ABAB, CDCD, EFEF, GG.\n\nNow watch this. Each line is usually in iambic pentameter. That is five beats, each an unstressed syllable followed by a stressed one. Say it with me. Shall I compare thee to a summer's day? Da DUM, da DUM, da DUM, da DUM, da DUM.\n\nLook at the volta, which means turn. Sonnet 18 begins by comparing a loved one to a summer day, finds summer too short and too changeable, and then in the couplet claims that the poem itself will keep the beloved alive.\n\nYour task is to describe the structure, explain iambic pentameter, and explain what a volta does. Take the four question check. A fixed form can hold a free heart. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 The Sonnet: Shakespeare and Poetic Form$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Shakespearean Tragedy: Hamlet and Macbeth$j$, $j${"readings": [{"title": "Proverbs 16 (King James Version)", "url": "/portal/bible/Proverbs/16"}], "body": "A tragedy is a drama in which a main character, the tragic hero, falls because of a flaw or a bad choice. The Greek thinker Aristotle described the tragic hero as admirable but flawed. Shakespeare wrote tragedies that explore ambition, revenge, jealousy and conscience.\n\nIn Macbeth, a Scottish general hears a prophecy from three witches that he will be king. Driven by ambition and urged on by his wife, he murders King Duncan. Guilt haunts him, and he grows more violent until he is defeated. His famous speech beginning Tomorrow, and tomorrow, and tomorrow shows a man who has lost all meaning. The lesson is that ambition without conscience destroys the person who pursues it.\n\nIn Hamlet, a Danish prince learns that his uncle murdered his father. Hamlet struggles over whether to take revenge, and the speech beginning To be, or not to be, that is the question, shows his inner conflict. Hamlet's delay is his flaw, and the play ends with many deaths.\n\nSoliloquy is a speech in which a character, alone on stage, speaks his thoughts aloud. Shakespeare uses soliloquy so the audience can hear the conflict inside.\n\nScripture also warns about ambition and pride. Proverbs 16:18 says, Pride goeth before destruction, and an haughty spirit before a fall.\n\nYour task: (1) Define tragic hero and soliloquy. (2) Choose Macbeth or Hamlet and explain the character's flaw. (3) Connect the lesson to Proverbs 16:18.\n\nFlorida standards: ELA.12.R.1.1, ELA.12.R.1.2, ELA.12.R.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.1, ELA.12.R.1.2, ELA.12.R.1.3", "script": "Now we turn to the stage. Listen, Shakespeare wrote comedies and histories, but his greatest fame comes from his tragedies. A tragedy is a drama where a main character, the tragic hero, falls because of a flaw or a bad choice.\n\nLet's look at Macbeth. A Scottish general hears three witches say he will be king. Ambition grows, his wife pushes him on, and he murders King Duncan. From that moment guilt follows him and he becomes more and more violent. By the end he says, Tomorrow, and tomorrow, and tomorrow, creeps in this petty pace. He has lost all meaning. Ambition without conscience destroys the very person who pursues it.\n\nNow watch this. In Hamlet, a Danish prince learns that his uncle murdered his father. Hamlet cannot decide what to do. His famous words, To be, or not to be, that is the question, show a mind torn by doubt. Those speeches are soliloquies, where a character alone on stage speaks his thoughts aloud so we hear the conflict inside.\n\nScripture gave the same warning long before. Proverbs 16:18 says, Pride goeth before destruction, and an haughty spirit before a fall.\n\nYour task is to define tragic hero and soliloquy, explain one character's flaw, and connect it to Proverbs. Take the four question check. Guard your heart. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Shakespearean Tragedy: Hamlet and Macbeth$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 The King James Bible as Literature$j$, $j${"readings": [{"title": "Psalm 19 (King James Version)", "url": "/portal/bible/Psalms/19"}], "body": "The King James Bible, first published in 1611, is one of the greatest works in English. King James I of England authorized a new translation, and about fifty scholars worked in teams at Westminster, Oxford and Cambridge. They built on earlier work, especially that of William Tyndale, who translated the New Testament from Greek and was put to death in 1536 for his work. Tyndale is said to have wanted every plowboy to know the Scriptures.\n\nThe translators aimed for accuracy, dignity and a style that could be read aloud. The result shaped the English language. Many everyday phrases come from it, such as the skin of my teeth, a fly in the ointment, the powers that be, the blind leading the blind, and a house divided against itself.\n\nNotice the literary features. Parallelism, used in Hebrew poetry, appears in Psalm 19:1: The heavens declare the glory of God; and the firmament sheweth his handywork. Metaphor and simile appear everywhere, as in Psalm 23, The LORD is my shepherd. Rhythm and repetition are found in Ecclesiastes 3, To every thing there is a season.\n\nA reader studies the Bible as literature to appreciate its craft, and as Scripture to receive its message. Both can be done together, and the first deepens the second.\n\nYour task: (1) Tell who authorized the King James Bible and the role of Tyndale. (2) Find two phrases in English that come from the Bible. (3) Identify one literary feature in Psalm 19:1 or Psalm 23 and explain its effect.\n\nFlorida standards: ELA.12.R.1.4, ELA.12.R.2.1, ELA.12.R.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.4, ELA.12.R.2.1, ELA.12.R.3.1", "script": "Welcome back. Listen, one book shaped the English language more than any other, and you hold it in your hands. The King James Bible was first published in 1611. King James the First authorized it, and about fifty scholars worked in teams at Westminster, Oxford and Cambridge.\n\nThey did not start from nothing. They built on the work of William Tyndale, who translated the New Testament from Greek and was put to death in 1536. He wanted every plowboy to know the Scriptures. Think about what that cost.\n\nNow watch this. The translators aimed at accuracy, dignity and a style that could be read aloud. Many phrases you use every day come from it: the skin of my teeth, a fly in the ointment, the powers that be, a house divided against itself.\n\nLook at the craft. Psalm 19:1 uses parallelism. The heavens declare the glory of God; and the firmament sheweth his handywork. Two lines say the same truth in different words. Psalm 23 uses a metaphor, The LORD is my shepherd. Ecclesiastes 3 uses rhythm and repetition, To every thing there is a season.\n\nWe can study the Bible as literature to admire its craft, and read it as Scripture to receive its message. Your task is to tell who authorized it and who prepared the way, find two phrases, and name one literary feature. Take the four question check. Honor the Word. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 The King James Bible as Literature$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Donne, Herbert and Milton: Faith in Poetry$j$, $j${"readings": [{"title": "1 Corinthians 15 (King James Version)", "url": "/portal/bible/1Corinthians/15"}], "body": "In the 1600s English poets wrote deeply about faith, doubt and the soul. John Donne, a poet and later a dean of Saint Paul's Cathedral, was a leading metaphysical poet. Metaphysical poets used surprising comparisons, called conceits, and argued with God and with death. In his sonnet beginning Death, be not proud, Donne speaks to death as if it were a defeated enemy, and ends with the line, Death, thou shalt die. His prose also gave us the words, No man is an island, entire of itself, a reminder that people belong to one another.\n\nGeorge Herbert, a country parson, wrote poems with simple, quiet faith, sometimes shaped like the subject itself, such as the poem Easter Wings, printed in the form of wings.\n\nJohn Milton wrote Paradise Lost, a long epic poem in blank verse, which is unrhymed iambic pentameter. Its aim, stated in the opening, was to justify the ways of God to men. It retells the fall of Adam and Eve in Genesis 3, with a vivid portrait of Satan. Milton became blind but kept composing, and in a sonnet on his blindness he concluded, They also serve who only stand and wait.\n\nYour task: (1) Define conceit and blank verse. (2) Explain how Donne treats death in Death, be not proud, and connect it to 1 Corinthians 15:55. (3) Tell what Paradise Lost retells and why Milton wrote it.\n\nFlorida standards: ELA.12.R.1.2, ELA.12.R.1.4, ELA.12.R.3.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.2, ELA.12.R.1.4, ELA.12.R.3.2", "script": "Now we step into the seventeenth century. Listen, this was a time when poets wrote about faith, doubt and the soul with real passion.\n\nJohn Donne was a leading metaphysical poet, and later the dean of Saint Paul's Cathedral. Metaphysical poets used surprising comparisons called conceits. In his sonnet Death, be not proud, Donne speaks to death as if it were a defeated enemy, and he ends, Death, thou shalt die. He wrote also that no man is an island, entire of itself. People belong to one another.\n\nGeorge Herbert was a country parson. His poems have a quiet faith, and one poem, Easter Wings, is even printed in the shape of wings on the page.\n\nNow watch this. John Milton wrote Paradise Lost, a long epic poem in blank verse, which means unrhymed iambic pentameter. He said he wanted to justify the ways of God to men. It retells Genesis 3, the fall of Adam and Eve, with a vivid picture of Satan. And listen to this, Milton went blind, but he kept composing. In a sonnet on his blindness, he wrote, They also serve who only stand and wait.\n\nDonne's closing thought echoes 1 Corinthians 15:55, O death, where is thy sting? O grave, where is thy victory? Your task is to define conceit and blank verse, explain Donne's view of death, and tell what Paradise Lost retells. Take the four question check. Faith can sing. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Donne, Herbert and Milton: Faith in Poetry$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: The Renaissance and the Word of God$j$, $j${"prompt": "Write a literary report of at least 300 words on Renaissance literature. Use complete sentences and label each part. Psalm 119:105 says, Thy word is a lamp unto my feet, and a light unto my path.\n\nPart 1: Choose one sonnet or one soliloquy. Quote one or two lines (under 25 words) and explain its meaning.\nPart 2: Explain one poetic form or device from this unit (sonnet, iambic pentameter, volta, conceit, blank verse or soliloquy) and show it at work in an example.\nPart 3: Explain the tragic hero and the flaw in Macbeth or Hamlet.\nPart 4: Describe the role of Tyndale and the translators in producing the King James Bible, and name two phrases that came from it.\nPart 5: Compare the way Donne, Herbert or Milton treats faith with a passage from Scripture.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: The Renaissance and the Word of God$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Words That Last$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains why you think some poems and plays last for centuries, (2) tells about a poem, song or passage of Scripture you know by heart and why it matters to you, (3) describes one lesson about pride, ambition or conscience from this unit, and (4) connects your answer to Psalm 19:14, which says, Let the words of my mouth, and the meditation of my heart, be acceptable in thy sight, O LORD, my strength, and my redeemer. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How does the form of a poem add to its meaning? Keep your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Words That Last$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: The Sonnet: Shakespeare and Poetic Form$j$, $j${"questions": [{"q": "A Shakespearean sonnet has:", "options": ["Fourteen lines", "Four lines", "Twenty lines", "Eight lines"]}, {"q": "The closing two lines of a Shakespearean sonnet are called:", "options": ["A caesura", "A couplet", "A stanza break", "A refrain"]}, {"q": "Iambic pentameter has:", "options": ["Three beats per line", "Ten rhymes per line", "Five unstressed and stressed beats per line", "No rhythm"]}, {"q": "A volta is:", "options": ["A turn in thought", "A type of rhyme", "A speaker's name", "A title"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Sonnet: Shakespeare and Poetic Form$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,2,0}'::int[], array[$j$A sonnet has fourteen lines.$j$,$j$The final two lines form a couplet.$j$,$j$Five iambs make ten syllables.$j$,$j$The volta changes the direction of the poem.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Sonnet: Shakespeare and Poetic Form$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Shakespearean Tragedy: Hamlet and Macbeth$j$, $j${"questions": [{"q": "A tragic hero is:", "options": ["A villain with no good qualities", "A comic servant", "A narrator only", "An admirable character who falls because of a flaw"]}, {"q": "A soliloquy is:", "options": ["A conversation between friends", "A speech in which a character alone speaks his thoughts", "A list of stage directions", "A dance"]}, {"q": "Macbeth's main flaw is:", "options": ["Laziness", "Unchecked ambition", "Generosity", "Cowardice at birth"]}, {"q": "Proverbs 16:18 warns that:", "options": ["Revenge is wise", "Pride goes before destruction", "Fame brings peace", "Wealth lasts forever"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Shakespearean Tragedy: Hamlet and Macbeth$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,1}'::int[], array[$j$The tragic hero is noble but flawed.$j$,$j$A soliloquy reveals inner conflict.$j$,$j$Ambition without conscience drives him to murder.$j$,$j$Pride leads to a fall.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Shakespearean Tragedy: Hamlet and Macbeth$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: The King James Bible as Literature$j$, $j${"questions": [{"q": "The King James Bible was first published in:", "options": ["1611", "1066", "1215", "1776"]}, {"q": "Which translator was put to death in 1536 for translating the New Testament?", "options": ["William Tyndale", "Chaucer", "King James", "Shakespeare"]}, {"q": "Parallelism in Hebrew poetry means:", "options": ["A one word line", "A story with a moral", "A list of names", "Two lines express related ideas in different words"]}, {"q": "Studying the Bible as literature helps a reader:", "options": ["Avoid its message", "Memorize dates only", "Skip the reading", "Appreciate its craft and deepen understanding"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The King James Bible as Literature$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,3,3}'::int[], array[$j$It was published in 1611.$j$,$j$Tyndale's work shaped the King James Version.$j$,$j$Psalm 19:1 is an example.$j$,$j$Craft and message go together.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The King James Bible as Literature$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Donne, Herbert and Milton: Faith in Poetry$j$, $j${"questions": [{"q": "A conceit is:", "options": ["A title page", "A stage direction", "A rhyming couplet", "A surprising extended comparison"]}, {"q": "Blank verse is:", "options": ["Free verse", "Prose", "Unrhymed iambic pentameter", "Rhymed couplets"]}, {"q": "In Death, be not proud, Donne says death:", "options": ["Should be feared", "Cannot be discussed", "Is all powerful", "Is defeated and will die"]}, {"q": "Paradise Lost retells:", "options": ["The Battle of Hastings", "A voyage to Canterbury", "The Trojan War", "The fall of Adam and Eve"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Donne, Herbert and Milton: Faith in Poetry$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,3}'::int[], array[$j$Metaphysical poets used conceits.$j$,$j$Milton used blank verse in Paradise Lost.$j$,$j$He ends, Death, thou shalt die.$j$,$j$It retells Genesis 3.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Donne, Herbert and Milton: Faith in Poetry$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: The Renaissance and the Word of God$j$, $j${"questions": [{"q": "The Renaissance means:", "options": ["Silence", "War", "Rebirth", "Exile"]}, {"q": "A Shakespearean sonnet rhymes:", "options": ["AABB CCDD", "No rhyme", "ABAB CDCD EFEF GG", "ABCABC"]}, {"q": "Macbeth falls mainly because of:", "options": ["Patience", "Generosity", "Ambition without conscience", "Honesty"]}, {"q": "A soliloquy is spoken by a character:", "options": ["In whispers to everyone", "Alone on stage", "To a king only", "In a crowd"]}, {"q": "The King James Bible was published in:", "options": ["1066", "1492", "1914", "1611"]}, {"q": "Who prepared the way for the King James translation?", "options": ["Chaucer", "Queen Victoria", "William Tyndale", "John Milton"]}, {"q": "Milton's Paradise Lost is written in:", "options": ["Prose", "Couplets", "Blank verse", "Sonnets"]}, {"q": "Donne ends Death, be not proud with:", "options": ["Fear death", "Death is great", "Death wins", "Death, thou shalt die"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Renaissance and the Word of God$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,2,1,3,2,2,3}'::int[], array[$j$It was a rebirth of learning and art.$j$,$j$Three quatrains and a couplet.$j$,$j$Ambition drives him to murder.$j$,$j$It reveals inner thoughts.$j$,$j$The date is 1611.$j$,$j$Tyndale translated the New Testament from Greek.$j$,$j$It uses unrhymed iambic pentameter.$j$,$j$He says death will die.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Renaissance and the Word of God$j$ on conflict (item_id) do nothing;
